import json, os
import boto3
def handler(event, context):
    result = {"marker": 'A', "function_version": context.function_version, "invoked_function_arn": context.invoked_function_arn}
    if event.get("s3"):
        try:
            r = boto3.client("s3").get_object(**event["s3"])
            result["s3"] = {"code": "Success", "size": len(r["Body"].read()), "version": r.get("VersionId")}
        except Exception as e:
            result["s3"] = {"code": getattr(e, "response", {}).get("Error", {}).get("Code"), "message": str(e)}
    return result

